<script setup lang="ts">
import FlowHeader from '../../components/FlowHeader.vue'
import { useStudio } from '../../studio'
const {current,labels,refresh,preview,save,running,imageUrl,networkError,go,edit,original,reuse,cancelCurrent,toggleFavorite}=useStudio()
</script>
<template><view class="shell"><FlowHeader :step="3" title="你的新造型" subtitle="查看效果，找到下一套心动搭配"/><view v-if="networkError" class="notice"><text>{{networkError}}</text><text class="link" @click="refresh">重试连接</text></view><view v-if="current?.kind==='tryon'" class="card result"><view class="title">试穿效果<text class="status">{{labels[current.status]}}</text></view><view v-if="current.result"><image class="result-image" :src="imageUrl(current.result)" mode="aspectFit" @click="preview(current.result)"/><view class="row"><button class="secondary" @click="preview(current.result)">放大查看</button><button class="secondary" @click="save(current.result)">保存图片</button></view><view v-if="original" class="compare"><image :src="imageUrl(original)" mode="aspectFit" @click="preview(original)"/><text class="muted">本次使用的原图 · 点击对比</text></view></view><view v-else class="waiting"><view v-if="!['failed','canceled'].includes(current.status)" class="spinner"/><text>{{['failed','canceled'].includes(current.status)?'本次生成未完成':labels[current.status]}}</text><text class="error" v-if="current.error">{{current.error}}</text><text class="muted" v-else>任务已保存，离开页面仍会继续。通常约 90 秒，具体以模型处理时间为准。</text></view><button v-if="current.status==='queued'" class="secondary" @click="cancelCurrent">取消排队</button><button v-if="current.result" class="secondary" @click="toggleFavorite(current.result)">{{current.result.favorite?'★ 已收藏这套搭配':'☆ 收藏这套搭配'}}</button><text class="muted explanation">{{new Date(current.created*1000).toLocaleString()}}</text><button v-if="!running()" class="primary" @click="reuse">{{current.status==='failed'?'修改搭配后重试':'调整这套搭配'}}</button><text v-if="!running()" class="muted explanation">返回服装页确认后才会再次生成并计费。</text></view><view v-else class="card waiting"><text>还没有试穿任务</text><button class="primary" @click="edit">开始试穿</button></view><button class="secondary" @click="go('history')">查看全部记录</button></view></template>
